 "content": "def transform(grid):
    """Decode adjoining 2x2 blocks: solid blocks are 1; three-cell blocks
    are colored by the missing corner (TL=2, BL=3, TR=4)."""
    h, w = len(grid), len(grid[0])
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    pieces = []
    for r in range(h - 1):
        for c in range(w - 1):
            corners = {(r, c): 2, (r, c + 1): 4,
                       (r + 1, c): 3, (r + 1, c + 1): None}
            block = set(corners)
            if block <= cells:
                pieces.append((block, 1))
            for missing, color in corners.items():
                shape = block - {missing}
                if color is not None and shape <= cells:
                    pieces.append((shape, color))

    def solve(remaining):
        if not remaining:
            return {}
        anchor = min(remaining)
        for shape, color in pieces:
            if anchor in shape and shape <= remaining:
                rest = solve(remaining - shape)
                if rest is not None:
                    return {**rest, **{cell: color for cell in shape}}
        return None

    decoded = solve(cells)
    if decoded is None:
        raise ValueError("8-cells cannot be decomposed into encoded blocks")
    return [[decoded.get((r, c), 0) for c in range(w)] for r in range(h)]

if __name__ == '__main__':
